import {readWatchlist} from './watchlist.js';
import {escapeHtml as esc} from './components.js';
import {fetchResearch,eventMarkup,coverageMarkup,markResearchRead,showEventHistory} from './research-view.js';
import {selectEvents} from './research-model.js';
import {openPdfViewer} from './pdf-viewer.js';
export function mountBriefing(root){
 const life=new AbortController();let request,version=0,data=null,viewer,opener,visible=location.pathname==='/',kind='all',stock='all',readFilter='unread',saving=false;
 root.className='surface watchlist-briefing';root.innerHTML='<div class="research-heading"><div><h2>관심종목 브리핑 <small data-unread-count></small></h2><p>읽지 않은 변경 사항 · 앞으로 14일 실적</p></div><div><button data-briefing="refresh" aria-label="브리핑 새로고침">새로고침</button><button data-briefing="open">전체 보기 →</button></div></div><div class="briefing-items" aria-live="polite"></div><p class="briefing-save-state" role="status"></p><div class="research-coverage"></div>';
 const dialog=document.createElement('dialog');dialog.className='briefing-dialog';dialog.setAttribute('aria-labelledby','briefing-title');dialog.innerHTML='<div class="research-heading"><h2 id="briefing-title">관심종목 브리핑</h2><button data-briefing="close" aria-label="브리핑 닫기">닫기 ×</button></div><div class="briefing-filters"><label>종목 <select aria-label="브리핑 종목" data-brief-stock></select></label><label>유형 <select aria-label="브리핑 유형" data-brief-kind><option value="all">전체</option><option value="earnings">실적·일정</option><option value="report">리포트</option><option value="manager">운용사</option><option value="price">주가</option></select></label><label>상태 <select aria-label="브리핑 읽음 상태" data-brief-read><option value="unread">읽지 않음</option><option value="all">전체</option></select></label><button data-briefing="read-all">현재 목록 읽음 처리</button></div><p class="briefing-save-state" role="status"></p><div class="briefing-all" aria-live="polite"></div><p class="research-note">읽음 상태는 이 브라우저의 식별자로 서버에 저장됩니다. 내용이 정정되면 다시 표시합니다.</p>';document.body.append(dialog);
 function events(){const saved=new Set(readWatchlist());return (data?.items||[]).filter(e=>saved.has(e.key));}
 function filtered(){return selectEvents(events(),{kind,stock}).filter(e=>readFilter==='all'||e.unread);}
 function grouped(items){const groups=new Map();for(const e of items){if(!groups.has(e.key))groups.set(e.key,[]);groups.get(e.key).push(e);}return [...groups].map(([key,rows])=>'<section class="briefing-stock-group"><h3><a data-nav href="/stock/'+esc(key.replace(':','/'))+'">'+esc(key)+'</a><small>'+rows.length+'건</small></h3>'+rows.map(e=>eventMarkup(e,{readControl:true})).join('')+'</section>').join('');}
 function render(){const keys=readWatchlist(),unread=selectEvents(events()).filter(e=>e.unread),recent=unread.slice(0,5),empty=keys.length?'새로운 소식이 없습니다':'별표로 관심종목을 등록하면 변경 사항을 모아 볼 수 있어요.';
  root.querySelector('[data-unread-count]').textContent=unread.length?'읽지 않음 '+unread.length+'건':'';
  root.querySelector('.briefing-items').innerHTML=recent.length?grouped(recent):'<p class="research-empty">'+empty+'</p>';root.querySelector('.research-coverage').innerHTML=coverageMarkup(data?.coverage);
  const sel=dialog.querySelector('[data-brief-stock]');sel.innerHTML='<option value="all">전체 종목</option>'+keys.map(k=>'<option value="'+esc(k)+'">'+esc(k)+'</option>').join('');if(!keys.includes(stock))stock='all';sel.value=stock;dialog.querySelector('[data-brief-kind]').value=kind;dialog.querySelector('[data-brief-read]').value=readFilter;
  const all=filtered();dialog.querySelector('.briefing-all').innerHTML=all.length?grouped(all):'<p class="research-empty">새로운 소식이 없습니다</p>';dialog.querySelector('[data-briefing="read-all"]').disabled=saving||!all.some(e=>e.unread&&e.eventId);
 }
 async function refresh(){request?.abort();request=new AbortController();const n=++version,keys=readWatchlist();render();if(!keys.length){data=null;render();return;}if(!visible&&!dialog.open)return;if(!data)root.querySelector('.briefing-items').innerHTML='<p role="status">관심종목 소식을 확인하고 있어요</p>';try{const next=await fetchResearch(keys,request.signal);if(n!==version)return;data=next;render();}catch{if(!request.signal.aborted&&n===version)root.querySelector('.briefing-save-state').textContent='브리핑을 불러오지 못했습니다. 새로고침해 주세요.';}}
 async function mark(items){const rows=items.filter(e=>e.unread&&e.eventId);if(!rows.length||saving)return;saving=true;try{await markResearchRead(rows,life.signal);for(const e of rows)e.unread=false;root.querySelector('.briefing-save-state').textContent='';dialog.querySelector('.briefing-save-state').textContent='';}catch{root.querySelector('.briefing-save-state').textContent=dialog.querySelector('.briefing-save-state').textContent='읽음 상태를 저장하지 못했습니다. 다시 시도해 주세요.';}finally{saving=false;render();}}
 function close(){dialog.close();opener?.focus();}
 function click(e){showEventHistory(e,life.signal);const b=e.target.closest('[data-briefing]');if(b){if(b.dataset.briefing==='refresh')refresh();if(b.dataset.briefing==='open'){opener=b;render();dialog.showModal();}if(b.dataset.briefing==='close')close();if(b.dataset.briefing==='read-all')mark(filtered());}
  const article=e.target.closest('[data-event-id]'),event=article&&events().find(r=>r.eventId===article.dataset.eventId);if(event&&e.target.closest('[data-event-read], [data-research-report], [data-research-date], a[data-nav]'))mark([event]);
  const report=e.target.closest('[data-research-report]');if(report){const r=data?.reports?.find(r=>r.id===report.dataset.researchReport);if(r?.attachment?.url){viewer?.close();viewer=openPdfViewer({...r,fields:{title:{value:r.title}}});}}
  const price=e.target.closest('[data-research-date]');if(price&&event){dialog.close();location.href='/stock/'+event.key.replace(':','/')+'?chartDate='+price.dataset.researchDate;}
  if(e.target.closest('a[data-nav]')&&dialog.open)dialog.close();}
 root.addEventListener('click',click,{signal:life.signal});dialog.addEventListener('click',click,{signal:life.signal});dialog.addEventListener('change',e=>{if(e.target.matches('[data-brief-stock]'))stock=e.target.value;if(e.target.matches('[data-brief-kind]'))kind=e.target.value;if(e.target.matches('[data-brief-read]'))readFilter=e.target.value;render();},{signal:life.signal});
 addEventListener('moa-research-read',e=>{for(const read of e.detail||[]){const item=data?.items?.find(i=>i.eventId===read.id&&i.eventRevision<=read.revision);if(item)item.unread=false;}render();},{signal:life.signal});
 addEventListener('moa-watchlist',refresh,{signal:life.signal});addEventListener('storage',e=>{if(e.key==='moa-watchlist-v1')refresh();},{signal:life.signal});refresh();const timer=setInterval(()=>{if(visible&&!document.hidden)refresh();},300000);
 return {setVisible(value){const changed=visible!==value;visible=value;if(changed&&value)refresh();},refresh,destroy(){life.abort();request?.abort();clearInterval(timer);viewer?.close();dialog.remove();}};
}

